import{_ as e,o,c as n,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"09 — Các Chức năng Quản trị Hệ thống Nền tảng (Admin Functions)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/09-admin-functions.md","filePath":"ba/09-admin-functions.md"}'),d={name:"ba/09-admin-functions.md"};function i(a,t,h,r,s,g){return o(),n("div",null,[...t[0]||(t[0]=[c('<h1 id="_09-—-cac-chuc-nang-quan-tri-he-thong-nen-tang-admin-functions" tabindex="-1">09 — Các Chức năng Quản trị Hệ thống Nền tảng (Admin Functions) <a class="header-anchor" href="#_09-—-cac-chuc-nang-quan-tri-he-thong-nen-tang-admin-functions" aria-label="Permalink to &quot;09 — Các Chức năng Quản trị Hệ thống Nền tảng (Admin Functions)&quot;">​</a></h1><p>&gt; Navigation: <a href="./README.html">← BA Overview &amp; Hub</a> · <a href="./08-subscription-billing.html">← 08 - Subscription &amp; Billing</a> · <a href="./10-roles-permissions-matrix.html">Tiếp: 10 - Roles &amp; Permissions Matrix →</a> &gt; &gt; <strong>Phạm vi FR chuẩn</strong> (đồng bộ 100% với <code>Các FR của hệ thống - Feature_Function Requirement.csv</code>): &gt; - <strong>Mục <code>3.10 Admin Functions</code></strong>: <strong>14 FR (<code>3.10.1</code> – <code>3.10.14</code>)</strong> | <code>UC-128</code> – <code>UC-141</code> (cùng <code>3.7.13 Crawl Schedule Config</code> thuộc quyền <code>Admin</code>) &gt; - Use Cases chi tiết: <a href="./use-cases/08-admin-functions.html">use-cases/08-admin-functions.md</a> · Đặc tả SRS: <a href="./../feature/srs/09-admin-functions/README.html">09-admin-functions</a></p><hr><h2 id="_1-bang-tong-hop-14-yeu-cau-chuc-nang-chuan-3-10-1-–-3-10-14" tabindex="-1">1. Bảng Tổng hợp 14 Yêu cầu Chức năng Chuẩn (<code>3.10.1</code> – <code>3.10.14</code>) <a class="header-anchor" href="#_1-bang-tong-hop-14-yeu-cau-chuc-nang-chuan-3-10-1-–-3-10-14" aria-label="Permalink to &quot;1. Bảng Tổng hợp 14 Yêu cầu Chức năng Chuẩn (`3.10.1` – `3.10.14`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (141-FR Baseline)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.10.1</code></strong></td><td style="text-align:center;"><code>UC-128</code></td><td style="text-align:left;"><strong>Push Notification</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Tạo và phát thông báo toàn hệ thống (<code>/admin/notifications</code>), hỗ trợ phân nhóm đối tượng nhận (Tất cả người dùng, chỉ <code>Owner</code>, theo gói đăng ký hoặc theo vai trò) qua WebSocket, FCM Mobile và Email (<code>BR-62</code>, <code>BR-65</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.2</code></strong></td><td style="text-align:center;"><code>UC-129</code></td><td style="text-align:left;"><strong>Platform Statistics Overview</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xem bảng điều khiển thống kê tổng quan toàn nền tảng (<code>/admin/dashboard</code>): tổng người dùng, số Agency &amp; Workspace đang hoạt động, tổng bài xuất bản trên 4 mạng xã hội, lưu lượng gọi AI và tổng doanh thu (<code>BR-61</code>, <code>BR-62</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.3</code></strong></td><td style="text-align:center;"><code>UC-130</code></td><td style="text-align:left;"><strong>System Health Monitoring</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Giám sát sức khỏe và tài nguyên thời gian thực của toàn bộ cụm Microservices (<code>/admin/health</code>): trạng thái <code>UP</code>/<code>DOWN</code>/<code>DEGRADED</code>, <code>%CPU</code>, <code>%RAM</code>, độ trễ API, hàng đợi RabbitMQ và kết nối PostgreSQL, MongoDB, Redis, ChromaDB, Neo4j (<code>BR-62</code>, <code>BR-65</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.4</code></strong></td><td style="text-align:center;"><code>UC-131</code></td><td style="text-align:left;"><strong>Content Moderation Queue</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xem và xử lý hàng đợi kiểm duyệt các nội dung bị bộ lọc an toàn (<code>3.6.33</code>) gắn cờ nghi ngờ vi phạm chính sách (<code>/admin/moderation</code>): phê duyệt cho phép lưu hành (<code>Approve</code>/<code>Dismiss</code>) hoặc xác nhận vi phạm để gỡ bỏ (<code>Confirm Violation</code>, <code>BR-42</code>, <code>BR-63</code>, <code>BR-65</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.5</code></strong></td><td style="text-align:center;"><code>UC-132</code></td><td style="text-align:left;"><strong>Update User Violation Status</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Cập nhật trạng thái xử lý vi phạm của tài khoản (<code>/admin/users/:userId/status</code>) giữa <code>ACTIVE</code>, <code>WARNED</code>, <code>SUSPENDED</code> và <code>BANNED</code> (kèm thu hồi toàn bộ phiên đăng nhập trên Redis và ghi bắt buộc lý do vào <code>audit_logs</code>, <code>BR-63</code>, <code>BR-65</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.6</code></strong></td><td style="text-align:center;"><code>UC-133</code></td><td style="text-align:left;"><strong>View User</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xem, tìm kiếm và lọc danh sách toàn bộ tài khoản người dùng trên hệ thống (<code>/admin/users</code>) theo Họ tên, Email, Vai trò, Trạng thái tài khoản và xem chi tiết các Agency/Workspace họ tham gia (<code>BR-62</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.7</code></strong></td><td style="text-align:center;"><code>UC-134</code></td><td style="text-align:left;"><strong>Create User</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Tạo mới tài khoản người dùng trực tiếp từ cổng quản trị (<code>/admin/users/new</code>): kiểm tra email duy nhất (<code>BR-01</code>), băm mật khẩu hoặc gửi email kích hoạt, gán vai trò hệ thống và ghi nhận vào <code>audit_logs</code> (<code>BR-62</code>, <code>BR-65</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.8</code></strong></td><td style="text-align:center;"><code>UC-135</code></td><td style="text-align:left;"><strong>Update User</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Chỉnh sửa thông tin hồ sơ hành chính và phân quyền cấp hệ thống của người dùng (<code>/admin/users/:userId/edit</code>), ngăn chặn việc tự hạ quyền hoặc khóa tài khoản <code>Admin</code> cuối cùng đang hoạt động (<code>BR-11</code>, <code>BR-62</code>, <code>BR-65</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.9</code></strong></td><td style="text-align:center;"><code>UC-136</code></td><td style="text-align:left;"><strong>Deactivate User</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Tạm khóa / vô hiệu hóa tài khoản người dùng (<code>/admin/users/:userId</code>): chuyển sang <code>INACTIVE</code>/<code>DEACTIVATED</code>, lập tức thu hồi mọi JWT token trên Redis (<code>BR-63</code>), chặn đăng nhập mới (<code>BR-05</code>) nhưng bảo toàn dữ liệu lịch sử và ghi <code>audit_logs</code> (<code>BR-65</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.10</code></strong></td><td style="text-align:center;"><code>UC-137</code></td><td style="text-align:left;"><strong>View AI Credit Price List</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Admin</code></td><td style="text-align:left;">Xem bảng cấu hình đơn giá tiêu hao AI Credit hiện hành của toàn hệ thống (<code>/admin/credit-prices</code>) cho đầy đủ các tác vụ AI kèm trạng thái kích hoạt và lịch sử cập nhật giá (<code>BR-48</code>, <code>BR-62</code>, <code>BR-64</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.11</code></strong></td><td style="text-align:center;"><code>UC-138</code></td><td style="text-align:left;"><strong>Update AI Credit Price</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Cập nhật trực tiếp đơn giá tiêu hao AI Credit (số nguyên dương hợp lệ) cho từng tác vụ AI; áp dụng cho các yêu cầu kế tiếp mà không làm thay đổi số credit đã khóa của các tiến trình AI đang chạy dở (<code>BR-48</code>, <code>BR-64</code>, <code>BR-65</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.12</code></strong></td><td style="text-align:center;"><code>UC-139</code></td><td style="text-align:left;"><strong>Import AI Credit Price CSV</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Tải lên, xem trước (<code>Preview</code>) và nhập hàng loạt bảng đơn giá AI Credit từ tệp CSV (<code>feature_code, model_tier, credit_cost, description</code>) theo giao dịch nguyên tử <code>all-or-nothing</code> (<code>BR-64</code>, <code>BR-65</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.13</code></strong></td><td style="text-align:center;"><code>UC-140</code></td><td style="text-align:left;"><strong>View Revenue Dashboard</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xem bảng điều khiển phân tích doanh thu thực thu từ các giao dịch <strong>SePay (VietQR)</strong> đã thanh toán (<code>PAID</code>) theo Ngày/Tuần/Tháng/Quý, tách bạch cơ cấu giữa Gói đăng ký (<code>Subscription Plans</code>) và Gói nạp thêm AI Credit (<code>Top-up Packs</code>, <code>BR-59</code>, <code>BR-61</code>, <code>BR-62</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.14</code></strong></td><td style="text-align:center;"><code>UC-141</code></td><td style="text-align:left;"><strong>Export Report File PDF</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Kết xuất và tải xuống tệp báo cáo quản trị định dạng <strong>PDF</strong> (<code>/admin/reports/export</code>) cho Báo cáo Doanh thu &amp; Giao dịch SePay, Báo cáo Tăng trưởng Người dùng &amp; Agency, và Báo cáo Tiêu thụ AI Credit (<code>BR-61</code>, <code>BR-62</code>, <code>BR-65</code>).</td></tr></tbody></table><hr><h2 id="_2-đac-ta-chi-tiet-cac-nhom-nghiep-vu-cong-quan-tri-admin-portal" tabindex="-1">2. Đặc tả Chi tiết Các Nhóm Nghiệp vụ Cổng Quản trị (<code>Admin Portal</code>) <a class="header-anchor" href="#_2-đac-ta-chi-tiet-cac-nhom-nghiep-vu-cong-quan-tri-admin-portal" aria-label="Permalink to &quot;2. Đặc tả Chi tiết Các Nhóm Nghiệp vụ Cổng Quản trị (`Admin Portal`)&quot;">​</a></h2><ol><li><strong>Truyền thông Hệ thống, Thống kê &amp; Giám sát Sức khỏe (<code>3.10.1</code> – <code>3.10.3</code>)</strong>: <ul><li>Cung cấp bức tranh vận hành tập trung theo thời gian thực trên cả 5 máy chủ sản xuất (<code>gateway</code>, <code>core</code>, <code>ai</code>, <code>crawl</code>, <code>edit-video</code>) và các kho dữ liệu (<code>PostgreSQL</code>, <code>MongoDB</code>, <code>Redis</code>, <code>ChromaDB</code>, <code>Neo4j</code>, <code>RabbitMQ</code>).</li></ul></li><li><strong>Kiểm duyệt An toàn Cộng đồng &amp; Quản lý Vòng đời Tài khoản (<code>3.10.4</code> – <code>3.10.9</code>)</strong>: <ul><li>Mọi thao tác nhạy cảm của <code>Admin</code> (<code>Update User Violation Status</code>, <code>Create User</code>, <code>Update User</code>, <code>Deactivate User</code>) đều bắt buộc ghi nhận vào bảng bất biến <code>audit_logs</code> (<code>BR-65</code>) và đồng bộ thu hồi phiên tức thì trên Redis (<code>jwt:blacklist:{jti}</code>) khi đình chỉ hoặc khóa tài khoản.</li><li>Bảo vệ an toàn quản trị: không cho phép khóa hoặc hạ quyền tài khoản <code>Admin</code> cuối cùng đang hoạt động trên nền tảng.</li></ul></li><li><strong>Định giá AI Credit, Đối soát Doanh thu SePay &amp; Kết xuất Báo cáo (<code>3.10.10</code> – <code>3.10.14</code>)</strong>: <ul><li>Bảng giá AI Credit (<code>ai_credit_operation_prices</code>) hiển thị minh bạch cho cả <code>Admin</code> và <code>Owner</code> (<code>3.10.10</code>), hỗ trợ cập nhật lẻ (<code>3.10.11</code>) hoặc nhập lô CSV nguyên tử (<code>3.10.12</code>).</li><li>Doanh thu tại <code>/admin/revenue</code> (<code>3.10.13</code>) chỉ tổng hợp từ các đơn hàng <strong>SePay (VietQR)</strong> đã xác nhận <code>PAID</code> và cho phép xuất chứng từ tổng hợp ra tệp PDF chuẩn (<code>3.10.14</code>).</li></ul></li></ol><hr><h2 id="_3-bang-tham-chieu-quy-tac-nghiep-vu-cong-quan-tri-br-62-–-br-65" tabindex="-1">3. Bảng Tham chiếu Quy tắc Nghiệp vụ Cổng Quản trị (<code>BR-62</code> – <code>BR-65</code>) <a class="header-anchor" href="#_3-bang-tham-chieu-quy-tac-nghiep-vu-cong-quan-tri-br-62-–-br-65" aria-label="Permalink to &quot;3. Bảng Tham chiếu Quy tắc Nghiệp vụ Cổng Quản trị (`BR-62` – `BR-65`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã BR</th><th style="text-align:left;">Tên Quy tắc</th><th style="text-align:left;">Quy định Ràng buộc Cụ thể</th><th style="text-align:left;">FR Áp dụng</th></tr></thead><tbody><tr><td style="text-align:center;"><code>BR-62</code></td><td style="text-align:left;"><strong>Cô lập Phân quyền Cấp Hệ thống (<code>SystemRole = ADMIN</code>)</strong></td><td style="text-align:left;">Toàn bộ các route <code>/admin/*</code> và nhóm API quản trị nền tảng (<code>3.10.1</code>–<code>3.10.9</code>, <code>3.10.11</code>–<code>3.10.14</code>, <code>3.7.13</code>) chỉ chấp nhận tài khoản mang <code>user_system_roles = ADMIN</code> đang <code>ACTIVE</code> (riêng <code>3.10.10 View AI Credit Price List</code> mở quyền đọc minh bạch cho cả <code>Owner</code>).</td><td style="text-align:left;"><code>3.10.1</code>–<code>3.10.14</code></td></tr><tr><td style="text-align:center;"><code>BR-63</code></td><td style="text-align:left;"><strong>Cưỡng chế Thu hồi Phiên &amp; Bảo vệ <code>Admin</code> Cuối cùng</strong></td><td style="text-align:left;">Khi <code>Admin</code> chuyển trạng thái tài khoản sang <code>SUSPENDED</code>, <code>BANNED</code> (<code>3.10.5</code>) hoặc <code>INACTIVE</code> (<code>3.10.9</code>), hệ thống lập tức thu hồi toàn bộ <code>user_refresh_tokens</code> và ghi khóa thu hồi <code>jwt:blacklist:{jti}</code> trên Redis; đồng thời chặn tuyệt đối thao tác tự khóa hoặc hạ quyền tài khoản <code>Admin</code> hoạt động cuối cùng.</td><td style="text-align:left;"><code>3.10.4</code>, <code>3.10.5</code>, <code>3.10.8</code>, <code>3.10.9</code></td></tr><tr><td style="text-align:center;"><code>BR-64</code></td><td style="text-align:left;"><strong>Cập nhật Nguyên tử Bảng Đơn giá AI Credit (<code>All-or-Nothing CSV</code>)</strong></td><td style="text-align:left;">Đơn giá AI Credit phải là số nguyên không âm hợp lệ; nhập bảng giá qua CSV (<code>3.10.12</code>) kiểm tra toàn bộ dòng trước khi ghi giao dịch nguyên tử vào <code>ai_credit_operation_prices</code> (lưu lịch sử biến động giá và không hồi tố lên các <code>ai_credit_reservations</code> đang chạy).</td><td style="text-align:left;"><code>3.10.10</code>–<code>3.10.12</code></td></tr><tr><td style="text-align:center;"><code>BR-65</code></td><td style="text-align:left;"><strong>Nhật ký Kiểm toán Bất biến (<code>Immutable Audit Trail</code>)</strong></td><td style="text-align:left;">Mọi hành động nhạy cảm của <code>Admin</code> (phát thông báo diện rộng, duyệt/gỡ nội dung vi phạm, gán gậy cảnh cáo <code>user_strikes</code>, xét khiếu nại <code>sanction_reviews</code>, tạo/sửa/vô hiệu hóa tài khoản, đổi giá credit, xuất báo cáo PDF) bắt buộc lưu bản ghi bất biến vào <code>audit_logs</code> kèm <code>actor_id</code>, <code>ip_address</code>, lý do và dữ liệu trước/sau.</td><td style="text-align:left;"><code>3.10.1</code>, <code>3.10.3</code>–<code>3.10.9</code>, <code>3.10.11</code>, <code>3.10.12</code>, <code>3.10.14</code></td></tr></tbody></table><hr><h2 id="_4-kien-truc-giam-sat-suc-khoe-đa-may-chu-kiem-duyet-ket-xuat-bao-cao" tabindex="-1">4. Kiến trúc Giám sát Sức khỏe Đa Máy chủ, Kiểm duyệt &amp; Kết xuất Báo cáo <a class="header-anchor" href="#_4-kien-truc-giam-sat-suc-khoe-đa-may-chu-kiem-duyet-ket-xuat-bao-cao" aria-label="Permalink to &quot;4. Kiến trúc Giám sát Sức khỏe Đa Máy chủ, Kiểm duyệt &amp; Kết xuất Báo cáo&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    COL[&quot;Host Collectors &amp; Health Targets&lt;br/&gt;(gateway, core, ai, crawl, edit-video)&quot;] --&gt;|&quot;Enroll &amp; push metrics&quot;| MON[&quot;MongoDB: monitoring_servers,&lt;br/&gt;monitoring_collectors, monitoring_health_targets&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CMP[&quot;3.6.33 Compliance Check&quot;] --&gt;|&quot;Flagged content&quot;| MOD[&quot;PostgreSQL: content_moderation_reviews,&lt;br/&gt;user_strikes, sanction_reviews&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ADM[&quot;Admin Console (/admin/*)&quot;] --&gt; MON</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ADM --&gt; MOD</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ADM --&gt;|&quot;Read PAID orders&quot;| REV[&quot;PostgreSQL: billing_payments,&lt;br/&gt;transactions, admin_report_exports&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ADM --&gt;|&quot;Broadcast&quot;| NTF[&quot;PostgreSQL: admin_notifications →&lt;br/&gt;user_notifications (LISTEN/NOTIFY) +admin_email_outbox&quot;]</span></span></code></pre></div><hr><h2 id="_5-anh-xa-thuc-the-co-so-du-lieu-cua-phan-he-admin" tabindex="-1">5. Ánh xạ Thực thể Cơ sở Dữ liệu Của Phân hệ <code>Admin</code> <a class="header-anchor" href="#_5-anh-xa-thuc-the-co-so-du-lieu-cua-phan-he-admin" aria-label="Permalink to &quot;5. Ánh xạ Thực thể Cơ sở Dữ liệu Của Phân hệ `Admin`&quot;">​</a></h2><ul><li><strong>PostgreSQL (<code>brandhub-business-service</code>)</strong>: <code>audit_logs</code>, <code>user_strikes</code>, <code>sanction_reviews</code>, <code>admin_account_operations</code>, <code>admin_email_outbox</code>, <code>admin_notifications</code>, <code>admin_report_exports</code>, <code>content_moderation_reviews</code>, <code>user_notifications</code>, <code>ai_credit_operation_prices</code>, <code>billing_plan_change_log</code>.</li><li><strong>MongoDB (<code>brandhub-business-service</code>)</strong>: <code>monitoring_servers</code>, <code>monitoring_collectors</code>, <code>monitoring_enrollments</code>, <code>monitoring_health_targets</code>, <code>report_jobs</code>.</li></ul><hr><h2 id="_6-co-che-xu-ly-vi-pham-cong-đong-strikes-danh-muc-bao-cao-pdf-quan-tri" tabindex="-1">6. Cơ chế Xử lý Vi phạm Cộng đồng (<code>Strikes</code>) &amp; Danh mục Báo cáo PDF Quản trị <a class="header-anchor" href="#_6-co-che-xu-ly-vi-pham-cong-đong-strikes-danh-muc-bao-cao-pdf-quan-tri" aria-label="Permalink to &quot;6. Cơ chế Xử lý Vi phạm Cộng đồng (`Strikes`) &amp; Danh mục Báo cáo PDF Quản trị&quot;">​</a></h2><h3 id="_6-1-thang-che-tai-tai-khoan-hang-đoi-kiem-duyet-3-10-4-–-3-10-5" tabindex="-1">6.1. Thang Chế tài Tài khoản &amp; Hàng đợi Kiểm duyệt (<code>3.10.4</code> – <code>3.10.5</code>) <a class="header-anchor" href="#_6-1-thang-che-tai-tai-khoan-hang-đoi-kiem-duyet-3-10-4-–-3-10-5" aria-label="Permalink to &quot;6.1. Thang Chế tài Tài khoản &amp; Hàng đợi Kiểm duyệt (`3.10.4` – `3.10.5`)&quot;">​</a></h3><ul><li><strong>Hàng đợi Kiểm duyệt (<code>Content Moderation Queue</code> — <code>3.10.4</code>)</strong>: Tiếp nhận các bài viết/hình ảnh bị bộ lọc an toàn (<code>3.6.33</code>) gắn cờ. <code>Admin</code> đối chiếu ngữ cảnh thương hiệu để chọn <strong>Bỏ cờ cho phép đăng (<code>Dismiss / Approve</code>)</strong> hoặc <strong>Xác nhận vi phạm (<code>Confirm Violation</code>)</strong>.</li><li>** leo thang Chế tài (<code>user_strikes</code> &amp; <code>sanction_reviews</code> — <code>3.10.5</code>)**: <ul><li><code>WARNED</code>: Ghi gậy cảnh cáo kèm thông báo nhắc nhở, tài khoản vẫn hoạt động.</li><li><code>SUSPENDED</code>: Tạm khóa đăng nhập có thời hạn, thu hồi ngay mọi JWT/Refresh Token đang mở trên Redis.</li><li><code>BANNED</code>: Khóa vĩnh viễn quyền truy cập hệ thống đối với vi phạm nghiêm trọng hoặc tái phạm nhiều lần; lưu hồ sơ khiếu nại tại <code>sanction_reviews</code>.</li></ul></li></ul><h3 id="_6-2-ba-loai-bao-cao-pdf-ket-xuat-chuan-3-10-14-export-report-file-pdf" tabindex="-1">6.2. Ba Loại Báo cáo PDF Kết xuất Chuẩn (<code>3.10.14 Export Report File PDF</code>) <a class="header-anchor" href="#_6-2-ba-loai-bao-cao-pdf-ket-xuat-chuan-3-10-14-export-report-file-pdf" aria-label="Permalink to &quot;6.2. Ba Loại Báo cáo PDF Kết xuất Chuẩn (`3.10.14 Export Report File PDF`)&quot;">​</a></h3><ol><li><strong>Báo cáo Doanh thu &amp; Giao dịch SePay (<code>SEPAY_REVENUE_REPORT</code>)</strong>: Tổng hợp doanh thu thực thu (<code>PAID</code>) theo chu kỳ chọn lọc, phân rã theo 6 gói đăng ký (<code>STUDIO_*</code>, <code>BASIC</code>, <code>PLUS</code>, <code>ENTERPRISE</code>) và các gói nạp lẻ AI Credit.</li><li><strong>Báo cáo Tăng trưởng Người dùng &amp; Tổ chức (<code>PLATFORM_GROWTH_REPORT</code>)</strong>: Thống kê người dùng mới, tỷ lệ kích hoạt Agency/Personal Studio, số lượng Workspace hoạt động và khối lượng bài xuất bản trên 4 nền tảng (<strong>Facebook, Instagram, TikTok, Threads</strong>).</li><li><strong>Báo cáo Tiêu thụ &amp; Hiệu suất AI (<code>AI_CONSUMPTION_REPORT</code>)</strong>: Phân tích tổng lượng AI Credit đã quyết toán theo 4 nhóm tác vụ tính phí (<code>CONTENT_GENERATE</code>, <code>AMBASSADOR_GENERATE</code>, <code>COMMERCIAL_IMAGE</code>, <code>VIDEO_GENERATE</code>) và tỷ lệ thành công của cụm worker.</li></ol>',23)])])}const m=e(d,[["render",i]]);export{u as __pageData,m as default};
